package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen1Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;

    // Constants mirroring the internal logic of TarArchiveOutputStream
    private static final int LONGFILE_GNU = 1;
    private static final int LONGFILE_TRUNCATE = 2;
    private static final int NAMELEN = 100; // Assuming 100 based on TarConstants logic

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOut = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_NormalName() throws IOException {
        String shortName = "test.txt";
        TarArchiveEntry entry = new TarArchiveEntry(shortName);
        entry.setSize(5);

        tarOut.putArchiveEntry(entry);

        // Verify no exception thrown and state updated
        // Since we can't easily access private fields like currName without reflection,
        // we verify that the method completes successfully.
        tarOut.closeArchiveEntry();
    }

    @Test
    public void testPutArchiveEntry_LongName_TruncateMode() throws IOException {
        // Create a name longer than NAMELEN
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < NAMELEN + 10; i++) {
            sb.append("a");
        }
        String longName = sb.toString();

        tarOut.setLongFileMode(LONGFILE_TRUNCATE);
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(10);

        tarOut.putArchiveEntry(entry);
        tarOut.closeArchiveEntry();

        Assert.assertTrue(out.size() > 0);
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_LongName_DefaultMode_ThrowsException() throws IOException {
        // Default longFileMode is usually 0 (not GNU or TRUNCATE)
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < NAMELEN + 10; i++) {
            sb.append("a");
        }
        String longName = sb.toString();

        TarArchiveEntry entry = new TarArchiveEntry(longName);
        tarOut.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_LongName_GNU_Mode() throws IOException {
        // Create a name longer than NAMELEN
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < NAMELEN + 10; i++) {
            sb.append("b");
        }
        String longName = sb.toString();

        tarOut.setLongFileMode(LONGFILE_GNU);
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(10);

        tarOut.putArchiveEntry(entry);

        // The GNU mode performs extra writes for the longlink entry
        // We check that the output stream received data
        Assert.assertTrue(out.size() > 0);
        tarOut.closeArchiveEntry();
    }

    @Test
    public void testPutArchiveEntry_Directory() throws IOException {
        TarArchiveEntry dirEntry = new TarArchiveEntry("dir/");
        dirEntry.setDirectory(true);

        tarOut.putArchiveEntry(dirEntry);
        tarOut.closeArchiveEntry();

        Assert.assertTrue(out.size() > 0);
    }

    @Test
    public void testPutArchiveEntry_FileWithContent() throws IOException {
        TarArchiveEntry fileEntry = new TarArchiveEntry("file.dat");
        fileEntry.setSize(10);

        tarOut.putArchiveEntry(fileEntry);
        // Simulate writing content
        tarOut.write(new byte[10]);
        tarOut.closeArchiveEntry();

        Assert.assertTrue(out.size() > 0);
    }

    /**
     * Mock class to bypass the need for complex TarConstants if they are not accessible,
     * but since we are testing the actual class, we use the real TarArchiveEntry.
     */
    private static class TarArchiveEntry extends org.apache.commons.compress.archivers.tar.TarArchiveEntry {
        public TarArchiveEntry(String name) throws IOException {
            super(name);
        }
    }
}
